create extension if not exists pgcrypto;
create table if not exists public.admins (id uuid primary key default gen_random_uuid(),auth_user_id uuid unique references auth.users(id) on delete cascade,email text unique not null,name text not null,status text not null default 'active' check(status in('active','suspended')),created_at timestamptz not null default now());
create table if not exists public.instructors (id uuid primary key default gen_random_uuid(),auth_user_id uuid unique references auth.users(id) on delete set null,email text unique not null,name text not null,bio text,avatar_url text,commission_rate numeric not null default 0.70 check(commission_rate between 0 and 1),status text not null default 'active' check(status in('active','suspended')),created_by_admin_id uuid references public.admins(id) on delete set null,created_at timestamptz not null default now());
alter table public.sahan_courses add column if not exists instructor_id uuid;
alter table public.sahan_courses add column if not exists base_quality_score numeric not null default 0;
alter table public.sahan_courses add column if not exists rank_score numeric not null default 0;
alter table public.sahan_courses add column if not exists admin_approved boolean not null default false;
alter table public.sahan_courses drop constraint if exists sahan_courses_instructor_id_fkey;
alter table public.sahan_courses add constraint sahan_courses_instructor_id_fkey foreign key(instructor_id) references public.instructors(id) on delete set null;
create table if not exists public.promotion_requests (id uuid primary key default gen_random_uuid(),instructor_id uuid not null references public.instructors(id) on delete cascade,course_id uuid not null references public.sahan_courses(id) on delete cascade,requested_duration_days int not null check(requested_duration_days between 1 and 90),requested_budget numeric check(requested_budget is null or requested_budget>=0),status text not null default 'pending' check(status in('pending','approved','rejected')),admin_notes text,reviewed_by_admin_id uuid references public.admins(id) on delete set null,created_at timestamptz not null default now(),reviewed_at timestamptz);
create table if not exists public.promotions (id uuid primary key default gen_random_uuid(),promotion_request_id uuid references public.promotion_requests(id) on delete set null,course_id uuid not null references public.sahan_courses(id) on delete cascade,tier text not null check(tier in('boosted','featured')),weight numeric not null default 10 check(weight between 0 and 25),amount_paid numeric not null default 0 check(amount_paid>=0),start_date timestamptz not null,end_date timestamptz not null,created_at timestamptz not null default now(),check(end_date>start_date));
create table if not exists public.rank_overrides (course_id uuid primary key references public.sahan_courses(id) on delete cascade,manual_score numeric not null default 0 check(manual_score between -50 and 50),set_by_admin_id uuid references public.admins(id) on delete set null,updated_at timestamptz not null default now());
create table if not exists public.payouts (id uuid primary key default gen_random_uuid(),instructor_id uuid not null references public.instructors(id) on delete cascade,amount numeric not null check(amount>=0),period_start date not null,period_end date not null,status text not null default 'pending' check(status in('pending','paid')),paid_at timestamptz,created_at timestamptz not null default now(),check(period_end>=period_start));
create index if not exists idx_sahan_courses_instructor on public.sahan_courses(instructor_id);create index if not exists idx_promotion_requests_instructor on public.promotion_requests(instructor_id);create index if not exists idx_promotion_requests_status on public.promotion_requests(status);create index if not exists idx_promotions_course_dates on public.promotions(course_id,start_date,end_date);create index if not exists idx_payouts_instructor on public.payouts(instructor_id);
create or replace function public.is_sahan_admin() returns boolean language sql stable security invoker set search_path=public as $$ select coalesce(auth.jwt()->'app_metadata'->>'role','')='admin' or coalesce(auth.jwt()->'user_metadata'->>'role','')='admin'; $$;
create or replace function public.get_course_rankings() returns table(id uuid,instructor_id uuid,title text,slug text,description text,cover_url text,category text,level text,price numeric,currency text,base_quality_score numeric,manual_score numeric,promotion_score numeric,effective_rank_score numeric) language sql stable security invoker set search_path=public as $$ select x.id,x.instructor_id,x.title,x.slug,x.description,x.cover_url,x.category,x.level,x.price,x.currency,x.base_quality_score,x.manual_score,x.promotion_score,x.base_quality_score+x.manual_score+x.promotion_score from (select c.id,c.instructor_id,c.title,c.slug,c.description,c.cover_url,c.category,c.level,c.price,c.currency,c.base_quality_score,coalesce(ro.manual_score,0) manual_score,coalesce(sum(case when p.start_date<=now() and p.end_date>now() then p.weight else 0 end),0) promotion_score from public.sahan_courses c left join public.rank_overrides ro on ro.course_id=c.id left join public.promotions p on p.course_id=c.id where c.admin_approved=true and c.status='published' group by c.id,ro.manual_score) x order by x.base_quality_score+x.manual_score+x.promotion_score desc; $$;
alter table public.admins enable row level security;alter table public.instructors enable row level security;alter table public.promotion_requests enable row level security;alter table public.promotions enable row level security;alter table public.rank_overrides enable row level security;alter table public.payouts enable row level security;
drop policy if exists "creators manage own courses" on public.sahan_courses;drop policy if exists "public can view published courses" on public.sahan_courses;drop policy if exists "approved courses are public" on public.sahan_courses;drop policy if exists "instructors view own courses" on public.sahan_courses;drop policy if exists "instructors update own courses" on public.sahan_courses;drop policy if exists "instructors can view own row" on public.instructors;drop policy if exists "instructors can update own row" on public.instructors;drop policy if exists "admins manage instructors" on public.instructors;drop policy if exists "instructors manage own promotion requests" on public.promotion_requests;drop policy if exists "instructors view own promotions" on public.promotions;drop policy if exists "admins manage promotions" on public.promotions;drop policy if exists "admins manage rank overrides" on public.rank_overrides;drop policy if exists "instructors view own payouts" on public.payouts;drop policy if exists "admins manage payouts" on public.payouts;drop policy if exists "admins view self" on public.admins;
create policy "approved courses are public" on public.sahan_courses for select to public using(admin_approved=true and status='published');
create policy "instructors view own courses" on public.sahan_courses for select to authenticated using(instructor_id in(select id from public.instructors where auth_user_id=auth.uid()) or public.is_sahan_admin() or(admin_approved=true and status='published'));
create policy "instructors update own courses" on public.sahan_courses for update to authenticated using(instructor_id in(select id from public.instructors where auth_user_id=auth.uid())) with check(instructor_id in(select id from public.instructors where auth_user_id=auth.uid()));
create policy "instructors can view own row" on public.instructors for select to authenticated using(auth_user_id=auth.uid() or public.is_sahan_admin());
create policy "instructors can update own row" on public.instructors for update to authenticated using(auth_user_id=auth.uid()) with check(auth_user_id=auth.uid());
create policy "admins manage instructors" on public.instructors for all to authenticated using(public.is_sahan_admin()) with check(public.is_sahan_admin());
create policy "instructors manage own promotion requests" on public.promotion_requests for all to authenticated using(instructor_id in(select id from public.instructors where auth_user_id=auth.uid()) or public.is_sahan_admin()) with check(instructor_id in(select id from public.instructors where auth_user_id=auth.uid()) or public.is_sahan_admin());
create policy "instructors view own promotions" on public.promotions for select to authenticated using(course_id in(select id from public.sahan_courses where instructor_id in(select id from public.instructors where auth_user_id=auth.uid())) or public.is_sahan_admin());
create policy "admins manage promotions" on public.promotions for all to authenticated using(public.is_sahan_admin()) with check(public.is_sahan_admin());
create policy "admins manage rank overrides" on public.rank_overrides for all to authenticated using(public.is_sahan_admin()) with check(public.is_sahan_admin());
create policy "instructors view own payouts" on public.payouts for select to authenticated using(instructor_id in(select id from public.instructors where auth_user_id=auth.uid()) or public.is_sahan_admin());
create policy "admins manage payouts" on public.payouts for all to authenticated using(public.is_sahan_admin()) with check(public.is_sahan_admin());
create policy "admins view self" on public.admins for select to authenticated using(auth_user_id=auth.uid() or public.is_sahan_admin());
